data.script:
// Mean Reversion Channel - MRI Variant
// Original Pine Script by fareidzulkifli, Mozilla Public License 2.0 (https://mozilla.org/MPL/2.0/)
// Ported to aggr. Multi timeframe labels (security / label.new) are not available in aggr and were left out.

srcType = option(type=list, label="Price source", options=["hlc3", "close", "hl2", "ohlc4"], default="hlc3")
filterType = option(type=list, label="Filter type", options=["SuperSmoother", "Ehlers EMA", "Gaussian", "Butterworth", "BandStop", "SMA", "EMA", "RMA"], default="SuperSmoother")
lookback = option(type=number, label="Lookback period", min=1, max=1000, step=1, default=200)
innerMult = option(type=number, label="Inner channel size multiplier", min=0.1, step=0.1, default=1)
outerMult = option(type=number, label="Outer channel size multiplier", min=0.1, step=0.001, default=2.415)
showChannel = option(type=checkbox, label="Draw channel", default=true)
showZones = option(type=checkbox, label="Draw zone (with channel)", default=true)
zoneTransparency = option(type=range, label="Zone transparency", min=0, max=100, step=1, default=60)
showLevels = option(type=checkbox, label="Show levels on price scale", default=true)
meanColor = option(type=color, label="Mean", default="#FFCD00")
innerColor = option(type=color, label="Inner channel (R1 / S1)", default="rgba(76,175,80,0.5)")
outerColor = option(type=color, label="Outer channel (R2 / S2)", default="rgba(255,82,82,0.5)")

// price source
var hi = $price.high
var lo = $price.low
var hlc = srcType === "close" ? $price.close : srcType === "hl2" ? (hi + lo) / 2 : srcType === "ohlc4" ? ($price.open + hi + lo + $price.close) / 4 : (hi + lo + $price.close) / 3

// history (src keeps up to 1000 bars back for the SMA filter)
src(1001) = hlc
cl = $price.close
tm = time

// on the first bar, history [1] points to the current bar (safe across realtime re-runs)
barCount = tm[1] === time ? 1 : barCount[1] + 1

// true range
var trueRange = barCount > 1 ? Math.max(hi - lo, Math.abs(hi - cl[1]), Math.abs(lo - cl[1])) : hi - lo

// SuperSmoother coefficients
var ssA = Math.exp(-Math.SQRT2 * Math.PI / lookback)
var ssC2 = 2 * ssA * Math.cos(Math.SQRT2 * Math.PI / lookback)
var ssC3 = -ssA * ssA
var ssC1 = 1 - ssC2 - ssC3

// channel width = SuperSmoother of true range
meanRange = barCount > 2 ? ssC1 * trueRange + ssC2 * meanRange[1] + ssC3 * meanRange[2] : trueRange

// running sum for the SMA filter
smaSum = barCount === 1 ? src : smaSum[1] + src - (src[lookback] || 0)

// mean line
if (barCount <= 2) {
  mean = src
} else if (filterType === "SuperSmoother") {
  mean = ssC1 * src + ssC2 * mean[1] + ssC3 * mean[2]
} else if (filterType === "SMA") {
  mean = smaSum / Math.min(barCount, lookback)
} else {
  // Ehlers Swiss Army Knife filter
  var cycle = 2 * Math.PI / lookback
  var c0 = 1
  var b0 = 1
  var b1 = 0
  var b2 = 0
  var a1 = 0
  var a2 = 0
  var alpha = 0
  var beta = 0
  var gamma = 0

  if (filterType === "Ehlers EMA") {
    alpha = (Math.cos(cycle) + Math.sin(cycle) - 1) / Math.cos(cycle)
    b0 = alpha
    a1 = 1 - alpha
  } else if (filterType === "Gaussian") {
    beta = 2.415 * (1 - Math.cos(cycle))
    alpha = -beta + Math.sqrt(beta * beta + 2 * beta)
    c0 = alpha * alpha
    a1 = 2 * (1 - alpha)
    a2 = -(1 - alpha) * (1 - alpha)
  } else if (filterType === "Butterworth") {
    beta = 2.415 * (1 - Math.cos(cycle))
    alpha = -beta + Math.sqrt(beta * beta + 2 * beta)
    c0 = alpha * alpha / 4
    b1 = 2
    b2 = 1
    a1 = 2 * (1 - alpha)
    a2 = -(1 - alpha) * (1 - alpha)
  } else if (filterType === "BandStop") {
    beta = Math.cos(cycle)
    gamma = 1 / Math.cos(cycle * 2 * 0.1)
    alpha = gamma - Math.sqrt(gamma * gamma - 1)
    c0 = (1 + alpha) / 2
    b1 = -2 * beta
    b2 = 1
    a1 = beta * (1 + alpha)
    a2 = -alpha
  } else if (filterType === "EMA") {
    alpha = 2 / (lookback + 1)
    b0 = alpha
    a1 = 1 - alpha
  } else if (filterType === "RMA") {
    alpha = 1 / lookback
    b0 = alpha
    a1 = 1 - alpha
  }

  mean = c0 * (b0 * src + b1 * src[1] + b2 * src[2]) + a1 * mean[1] + a2 * mean[2]
}

// bands
var up1 = mean + meanRange * Math.PI * innerMult
var dn1 = mean - meanRange * Math.PI * innerMult
var up2 = mean + meanRange * Math.PI * outerMult
var dn2 = mean - meanRange * Math.PI * outerMult
var zr = meanRange * 0.5

// gradient zones around the outer channel (red outside -> yellow inside)
if (showChannel && showZones) {
  cloudarea(up2 + zr * 3, up2 + zr * 4, positiveColor=`rgba(255,0,0,${1 - zoneTransparency / 100})`, negativeColor=`rgba(255,0,0,${1 - zoneTransparency / 100})`, higherLineColor="transparent", lowerLineColor="transparent")
  cloudarea(up2 + zr * 2, up2 + zr * 3, positiveColor=`rgba(255,66,0,${1 - zoneTransparency / 100})`, negativeColor=`rgba(255,66,0,${1 - zoneTransparency / 100})`, higherLineColor="transparent", lowerLineColor="transparent")
  cloudarea(up2 + zr, up2 + zr * 2, positiveColor=`rgba(255,93,0,${1 - zoneTransparency / 100})`, negativeColor=`rgba(255,93,0,${1 - zoneTransparency / 100})`, higherLineColor="transparent", lowerLineColor="transparent")
  cloudarea(up2, up2 + zr, positiveColor=`rgba(255,116,0,${1 - zoneTransparency / 100})`, negativeColor=`rgba(255,116,0,${1 - zoneTransparency / 100})`, higherLineColor="transparent", lowerLineColor="transparent")
  cloudarea(up2 - zr, up2, positiveColor=`rgba(255,151,0,${1 - zoneTransparency / 100})`, negativeColor=`rgba(255,151,0,${1 - zoneTransparency / 100})`, higherLineColor="transparent", lowerLineColor="transparent")
  cloudarea(up2 - zr * 2, up2 - zr, positiveColor=`rgba(255,174,0,${1 - zoneTransparency / 100})`, negativeColor=`rgba(255,174,0,${1 - zoneTransparency / 100})`, higherLineColor="transparent", lowerLineColor="transparent")
  cloudarea(up2 - zr * 3, up2 - zr * 2, positiveColor=`rgba(255,197,0,${1 - zoneTransparency / 100})`, negativeColor=`rgba(255,197,0,${1 - zoneTransparency / 100})`, higherLineColor="transparent", lowerLineColor="transparent")
  cloudarea(up2 - zr * 4, up2 - zr * 3, positiveColor=`rgba(255,205,0,${1 - zoneTransparency / 100})`, negativeColor=`rgba(255,205,0,${1 - zoneTransparency / 100})`, higherLineColor="transparent", lowerLineColor="transparent")

  cloudarea(dn2 - zr * 4, dn2 - zr * 3, positiveColor=`rgba(255,0,0,${1 - zoneTransparency / 100})`, negativeColor=`rgba(255,0,0,${1 - zoneTransparency / 100})`, higherLineColor="transparent", lowerLineColor="transparent")
  cloudarea(dn2 - zr * 3, dn2 - zr * 2, positiveColor=`rgba(255,66,0,${1 - zoneTransparency / 100})`, negativeColor=`rgba(255,66,0,${1 - zoneTransparency / 100})`, higherLineColor="transparent", lowerLineColor="transparent")
  cloudarea(dn2 - zr * 2, dn2 - zr, positiveColor=`rgba(255,93,0,${1 - zoneTransparency / 100})`, negativeColor=`rgba(255,93,0,${1 - zoneTransparency / 100})`, higherLineColor="transparent", lowerLineColor="transparent")
  cloudarea(dn2 - zr, dn2, positiveColor=`rgba(255,116,0,${1 - zoneTransparency / 100})`, negativeColor=`rgba(255,116,0,${1 - zoneTransparency / 100})`, higherLineColor="transparent", lowerLineColor="transparent")
  cloudarea(dn2, dn2 + zr, positiveColor=`rgba(255,151,0,${1 - zoneTransparency / 100})`, negativeColor=`rgba(255,151,0,${1 - zoneTransparency / 100})`, higherLineColor="transparent", lowerLineColor="transparent")
  cloudarea(dn2 + zr, dn2 + zr * 2, positiveColor=`rgba(255,174,0,${1 - zoneTransparency / 100})`, negativeColor=`rgba(255,174,0,${1 - zoneTransparency / 100})`, higherLineColor="transparent", lowerLineColor="transparent")
  cloudarea(dn2 + zr * 2, dn2 + zr * 3, positiveColor=`rgba(255,197,0,${1 - zoneTransparency / 100})`, negativeColor=`rgba(255,197,0,${1 - zoneTransparency / 100})`, higherLineColor="transparent", lowerLineColor="transparent")
  cloudarea(dn2 + zr * 3, dn2 + zr * 4, positiveColor=`rgba(255,205,0,${1 - zoneTransparency / 100})`, negativeColor=`rgba(255,205,0,${1 - zoneTransparency / 100})`, higherLineColor="transparent", lowerLineColor="transparent")
}

if (showChannel) {
  line(mean, color=meanColor, lineWidth=2, lastValueVisible=showLevels, priceLineVisible=showLevels)
  line(up1, color=innerColor, lineStyle=1, lastValueVisible=showLevels, priceLineVisible=showLevels)
  line(dn1, color=innerColor, lineStyle=1, lastValueVisible=showLevels, priceLineVisible=showLevels)
  line(up2, color=outerColor, lastValueVisible=showLevels, priceLineVisible=showLevels)
  line(dn2, color=outerColor, lastValueVisible=showLevels, priceLineVisible=showLevels)
}
